INSERT INTO public.essay_submissions (user_id, tema, texto, nota_total, analise_completa, created_at) VALUES
(:MALU_ID, 'Saúde mental de jovens na era digital',
'A saúde mental emerge como preocupação crítica na contemporaneidade, afetada profundamente pela revolução digital. Adolescentes enfrentam pressões inéditas: exposição constante, comparação social amplificada, cyberbullying persistente, dependência comportamental de redes sociais. Pesquisas indicam aumento de ansiedade, depressão e transtornos do sono em populações jovens. Paradoxalmente, tecnologia que promete conexão frequentemente gera isolamento psíquico. Combater essa crise requer abordagem multifatorial: educação sobre saúde mental nas escolas, regulação de algoritmos predatórios, acesso a atendimento psicológico adequado, envolvimento parental consciente. Além disso, é crucial desconstruir narrativas de perfeição online. Organizações de saúde pública precisam reconhecer saúde mental com mesma urgência que epidemias físicas. Quando priorizamos bem-estar emocional de jovens, investimos em sociedade mais saudável e resiliente.',
580, '{"C1":{"score":90,"feedback":"Excelente problemática, bem contextualizada na era digital"},"C2":{"score":88,"feedback":"Argumentação clara com causa-efeito bem estabelecido"},"C3":{"score":86,"feedback":"Bom raciocínio, conectando digital a saúde mental"},"C4":{"score":84,"feedback":"Linguagem apropriada, progressão adequada"},"C5":{"score":85,"feedback":"Conclusão reforça relevância"}'::jsonb,
NOW() - INTERVAL '28 days'),
(:MALU_ID, 'Acesso à educação como base para desenvolvimento social',
'Educação de qualidade é direito inalienável que deveria ser garantido universalmente, entretanto permanece inacessível para bilhões. Desigualdade no acesso educacional perpet ua ciclos de pobreza, limitando mobilidade social. Estudantes de baixa renda frequentam escolas precárias com infraestrutura inadequada, professores desvalorizados, ausência de recursos. Consequência: conhecimento insuficiente, habilidades limitadas, oportunidades restritas. Investimento público robusto é imperativo: aumentar orçamento educacional, melhorar salários docentes, modernizar infraestrutura, garantir merenda escolar. Além disso, educação deve ser inclusiva: contemplar pessoas com deficiências, minorias, populações rurais. Quando todos têm acesso a educação de qualidade, economia cresce, crime diminui, saúde melhora. Desenvolvimento sustentável é impossível sem educação universal. O custo de não agir excede infinitamente o investimento necessário. Sociedades que priorizaram educação tornaram-se potências econômicas e democráticas.',
680, '{"C1":{"score":94,"feedback":"Contextualização magistral de desigualdade educacional"},"C2":{"score":92,"feedback":"Argumentação robusta, múltiplas dimensões (econômica, social, saúde)"},"C3":{"score":90,"feedback":"Raciocínio crítico bem desenvolvido"},"C4":{"score":88,"feedback":"Excelente progressão e clareza"},"C5":{"score":88,"feedback":"Conclusão que universaliza impacto"}'::jsonb,
NOW() - INTERVAL '21 days'),
(:MALU_ID, 'Violência urbana: reflexo de desigualdade estrutural',
'Violência urbana não é fenômeno isolado; é sintoma de desigualdade estrutural enraizada. Comunidades periféricas enfrentam violência desproporcional consequência de falta de acesso a educação, saúde, oportunidades econômicas. Sistema de segurança pública, historicamente militarizado, perpetua ciclo de brutalidade ao invés de resolver. Abordagens puramente repressivas falharam sistematicamente. Transformação genuína requer investimento preventivo: educação de qualidade, geração de emprego, saneamento básico, acesso à cultura e lazer. Quando jovens veem perspectivas de futuro digno, violência diminui naturalmente. Além disso, reforma policial é essencial: capacitação em direitos humanos, desincentivo a execuções extrajudiciais, accountability efetiva. Justiça restaurativa pode substituir punição pura. Exemplos internacionais demonstram que investimento em pessoas reduz violência mais efetivamente que aprisionamento em massa. Sociedade que deseja segurança deve estar disposta a investir em dignidade humana de suas periferias.',
760, '{"C1":{"score":97,"feedback":"Análise sofisticada da raiz estrutural da violência"},"C2":{"score":95,"feedback":"Argumentação refinada com propostas concretas e baseadas em evidência"},"C3":{"score":94,"feedback":"Reflexão crítica profunda sobre justiça e prevenção"},"C4":{"score":92,"feedback":"Excelente domínio de linguagem e fluidez"},"C5":{"score":92,"feedback":"Conclusão poderosa que sintetiza bem"}'::jsonb,
NOW() - INTERVAL '14 days'),
(:MALU_ID, 'Sustentabilidade climática: responsabilidade das gerações presentes',
'Mudanças climáticas não são mais previsão distante; são realidade que redefine geografia humana. Aquecimento global causa eventos climáticos extremos, extinção em massa, migração forçada. Responsabilidade histórica recai desproporcionalmente sobre nações industrializadas que acumularam emissões por séculos. Transição energética é imperativa: substituição de combustíveis fósseis por renováveis, proteção de biomas (especialmente Amazônia), transformação de agricultura industrial. Tecnologias limpas existem; faltam vontade política e investimento. Empresas devem assumir responsabilidade corporativa genuine; greenwashing é insuficiente. Cidadãos podem reduzir consumo, escolher produtos sustentáveis, pressionar governos. Mas mudança sistêmica é responsabilidade primária de Estados. Justiça climática exige que países ricos liderem transição, reconhecendo dívida histórica. Cidades e regiões já implementam soluções: transporte público eficiente, energias renováveis, economia circular. Inação condenaria futuras gerações a catástrofe. Nossa geração será julgada pela coragem que teve de transformar sistemas que beneficiam nossas economias.',
840, '{"C1":{"score":99,"feedback":"Contextualização excepcional que articula urgência, justiça e responsabilidade"},"C2":{"score":98,"feedback":"Argumentação sofisticada com dimensões históricas, políticas e éticas"},"C3":{"score":97,"feedback":"Reflexão crítica extraordinária sobre justiça climática"},"C4":{"score":96,"feedback":"Domínio exemplar de linguagem com precisão e elegância"},"C5":{"score":96,"feedback":"Conclusão magistral que projeta julgamento histórico"}'::jsonb,
NOW() - INTERVAL '7 days'),
(:MALU_ID, 'Diversidade cultural: riqueza que fortalece democracia',
'Democracias genuínas celebram diversidade como ativo fundamental, não ameaça a ser contida. Pluralismo cultural, religioso, étnico enriquece sociedades: traz perspectivas múltiplas, estimula criatividade, fortifica coesão social através do respeito mútuo. Contudo, movimentos populistas globalmente exploram medo da diferença, polarizando sociedades. Brasil, país etnicamente plural, historicamente minimizou herança africana e indígena. Educação deve ensinar história verdadeira incluindo contribuições de grupos marginalizados. Políticas de ação afirmativa corrigem injustiças históricas. Representação em espaços de poder (governo, mídia, academia) não é favor; é construção de democracia legítima. Quando vozes diversas participam na tomada de decisão, políticas são mais justas e efetivas. Intolerância é luxo que democracia não pode permitir; alimenta autoritarismo. Sociedades multiculturais bem gerenciadas prosperam economicamente e culturalmente. O desafio é transformar diversidade de facto em harmonia deliberada. Quando celebramos diferenças e construímos instituições inclusivas, fortalecemos laços democráticos.',
920, '{"C1":{"score":100,"feedback":"Contextualização brilhante que conecta democracia, diversidade e justiça histórica"},"C2":{"score":100,"feedback":"Argumentação magistral integrando múltiplas dimensões (cultural, política, econômica)"},"C3":{"score":99,"feedback":"Reflexão crítica excepcional sobre democracia genuína"},"C4":{"score":99,"feedback":"Domínio extraordinário de linguagem e progressão"},"C5":{"score":99,"feedback":"Conclusão poderosa que sintetiza e projeta transformação"}'::jsonb,
NOW() - INTERVAL '0 days');

