-- 7. ESSAY_SUBMISSIONS — PEDRO (4 redações: 520 → 940)
-- ═══════════════════════════════════════════════════════════════════════════════

INSERT INTO public.essay_submissions (user_id, tema, texto, nota_total, analise_completa, created_at) VALUES
(:PEDRO_ID, 'Privacidade digital: direito em risco',
'Coleta massiva de dados pessoais é realidade contemporânea frequentemente invisibilizada. Grandes empresas de tecnologia, governo, intermediários comerciais possuem informações íntimas sobre bilhões de pessoas: histórico de buscas, localização, preferências, comportamentos. Isso cria vulnerabilidade: roubo de identidade, discriminação algorítmica, vigilância estatal, manipulação comportamental. Direito à privacidade, fundamental em democracias, está sendo erodido. Legislação como LGPD no Brasil e GDPR na Europa representam avanços, mas implementação é fraca. Multas a empresas são insuficientes se lucros continuam exponenciais. Educação digital é crucial: cidadãos devem entender riscos. Regulação deve ser mais rigorosa: proibir venda de dados sem consentimento explícito, criar direitos de portabilidade, permitir apagamento de dados. Criptografia deve ser direito, não privilégio. Tecnologia descentralizada oferece alternativas. Quando privacidade é protegida, liberdade individual e democracia são fortalecidas. Futuro equilibrado exige que privacidade não seja tradable commodity.',
620, '{"C1":{"score":92,"feedback":"Contextualização clara dos riscos da coleta de dados"},"C2":{"score":90,"feedback":"Argumentação bem estruturada com exemplos de legislação"},"C3":{"score":88,"feedback":"Raciocínio crítico sobre direitos fundamentais"},"C4":{"score":86,"feedback":"Bom domínio de linguagem e progressão"},"C5":{"score":85,"feedback":"Conclusão que reforça importância"}'::jsonb,
NOW() - INTERVAL '21 days'),
(:PEDRO_ID, 'Inteligência artificial: governança para impedir distopia',
'Inteligência artificial transformará trabalho, educação, saúde, defesa. Benefícios potenciais são extraordinários: diagnóstico de doenças, educação personalizada, otimização de recursos. Riscos são igualmente enormes: desemprego tecnológico massivo, perda de privacidade através de vigilância, viés discriminatório perpetuado algoritmicamente, concentração de poder em corporações tech. Sistemas de IA já discriminam: reconhecimento facial falha com rostos escuros, algoritmos de contratação favorecem homens, diagnóstico médico é impreciso com minorias étnicas. Governança é urgente. Regulação deve exigir transparência: explicabilidade de decisões, auditoria de viés, accountability quando causa dano. Desenvolvimento deve ser inclusivo: pesquisadores diversos, representação de grupos afetados. Educação massiva em IA-literacy é necessária. Benefícios de IA devem ser compartilhados socialmente, não apropriados apenas por acionistas corporativos. Renda básica universal pode mitigar desemprego tecnológico. Quando IA é governada por princípios democráticos e justos, oferece caminho para prosperidade compartilhada. Distopia é opcional, não inevitável.',
740, '{"C1":{"score":96,"feedback":"Contextualização excepcional de benefícios e riscos da IA"},"C2":{"score":94,"feedback":"Argumentação robusta com exemplos concretos de viés"},"C3":{"score":92,"feedback":"Raciocínio crítico sobre governança e justiça"},"C4":{"score":90,"feedback":"Excelente progressão e clareza"},"C5":{"score":90,"feedback":"Conclusão que opõe determinismo a agência"}'::jsonb,
NOW() - INTERVAL '14 days'),
(:PEDRO_ID, 'Desinformação: defesa da democracia através de literacia digital',
'Desinformação é arma moderna que ameaça fundamentos democráticos. Redes sociais, algoritmos de recomendação, bots de propaganda multiplicam conteúdo falso. Pessoas compartilham notícias sem verificar fontes. Desinformação sobre saúde mata; sobre política corrompe eleições; sobre minorias incita violência. Combate requer múltiplas frentes. Plataformas digitais devem remover desinformação demonstrada, reduzir amplificação de conteúdo não verificado, transparentizar algoritmos. Jornalismo de qualidade deve ser valorizado e financiado, oferecendo alternativa confiável. Educação é arma mais poderosa: ensinar pensamento crítico desde infância, como identificar fontes confiáveis, como reagir a viés cognitivo. Campanhas públicas podem demonstrar técnicas de manipulação. Fact-checking profissional deve ser acessível. Legislação contra desinformação é delicada: deve coibir mentiras provadas sem censurar discurso legítimo. Democracias que ignoram desinformação descambam para autoritarismo. Vigilância sobre informação requer equilíbrio entre segurança epistêmica e liberdade. Quando cidadãos são críticos e informados, desinformação perde poder.',
840, '{"C1":{"score":98,"feedback":"Contextualização magistral de ameaça desinformação a democracias"},"C2":{"score":96,"feedback":"Argumentação sofisticada abordando múltiplas soluções integradas"},"C3":{"score":95,"feedback":"Reflexão crítica profunda sobre epistemologia e liberdade"},"C4":{"score":94,"feedback":"Excelente domínio de linguagem com nuance"},"C5":{"score":93,"feedback":"Conclusão que reafirma agência cidadã"}'::jsonb,
NOW() - INTERVAL '7 days'),
(:PEDRO_ID, 'Transformação digital inclusiva: reduzindo lacunas tecnológicas',
'Divisão digital não é apenas sobre acesso a tecnologia; é sobre capital social, econômico, cultural. Bilhões vivem em zonas com internet fraca ou inexistente. Mesmo onde há cobertura, analfabetismo digital exclui populações inteiras. Educação remota, telemedicina, government online presume conectividade e habilidades que grupos vulneráveis não possuem. Desigualdade digital perpetua desigualdade econômica. Solução requer investimento estatal maciço: infraestrutura em áreas rurais, educação digital universal, computadores acessíveis. Parcerias público-privadas podem acelerar, mas lucro não pode ser único objetivo. Inovação deve estar a serviço de inclusão. Programas de treinamento digital específicos para adultos com pouca educação formal. Conteúdo em múltiplas línguas e formatos. Tecnologia deve ser desenhada para incluir pessoas com deficiências. Quando populações marginalizadas têm acesso real a tecnologia e sabem usá-la, participam na economia digital, acessam informação, têm voz política. Inclusão digital não é luxo; é necessidade para coesão social e desenvolvimento. Deixar pessoas para trás tecnologicamente é opção política de sociedades injustas.',
940, '{"C1":{"score":100,"feedback":"Contextualização excepcional que diferencia acesso de inclusão real"},"C2":{"score":100,"feedback":"Argumentação magistral integrando economia, educação, justiça social"},"C3":{"score":99,"feedback":"Reflexão crítica extraordinária sobre tecnologia e equidade"},"C4":{"score":99,"feedback":"Domínio exemplar de linguagem com sofisticação"},"C5":{"score":98,"feedback":"Conclusão poderosa que articula escolha política e responsabilidade"}'::jsonb,
NOW() - INTERVAL '0 days');

