-- 8. ESSAY_SUBMISSIONS — AMANDA (5 redações: 680 → 880)
-- ═══════════════════════════════════════════════════════════════════════════════

INSERT INTO public.essay_submissions (user_id, tema, texto, nota_total, analise_completa, created_at) VALUES
(:AMANDA_ID, 'Intolerância religiosa: reafirmando liberdade de consciência',
'Intolerância religiosa persistindo no século XXI é indício de falha moral coletiva. Pessoas são mortas, aprisionadas, discriminadas por suas crenças. Religiões de matriz africana no Brasil enfrentam sincretismo forçado e violência aberta. Comunidades LGBTQIA+ são expulsas de igrejas. Judeus sofrem séculos de antissemitismo ressurgente. Muçulmanos enfrentam islamofobia crescente. Paradoxo: liberdade religiosa é direito humano fundamental, mas praticada seletivamente. Estados devem proteger liberdade de consciência para todos, inclusive de não-crentes. Educação deve apresentar história das religiões com respeito, mostrando contribuições múltiplas. Lideranças religiosas responsáveis devem condenar inequivocamente intolerância em seus próprios contextos. Leis contra crimes de ódio precisam de aplicação rigorosa. Diálogo inter-religioso, quando genuíno, reduz preconceitos. Cada tradição oferece sabedoria; humanidade é enriquecida pela coexistência respeitosa. Quando tolerância é real, não apenas tolerância de fachada, sociedades florescem espiritualmente.',
720, '{"C1":{"score":96,"feedback":"Contextualização magistral de intolerância religiosa global"},"C2":{"score":94,"feedback":"Argumentação robusta com exemplos específicos"},"C3":{"score":92,"feedback":"Raciocínio crítico sobre liberdade de consciência"},"C4":{"score":90,"feedback":"Excelente progressão e clareza"},"C5":{"score":90,"feedback":"Conclusão que universaliza benefício"}'::jsonb,
NOW() - INTERVAL '28 days'),
(:AMANDA_ID, 'Direitos LGBTQIA+: cidadania plena como imperativo democrático',
'Igualdade de direitos é conceito que ninguém pode negar, mas LGBTQIA+ frequentemente são excluídos de proteções básicas. Violência contra pessoas trans é epidêmica; Brasil lidera em assassinatos de trans globalmente. Discriminação em empregos, saúde, educação é sistemática. Casamento entre pessoas do mesmo sexo permanece ilegal em dezenas de países. Direitos reprodutivos e parentalidade são constantemente contestados. Cidadania plena para LGBTQIA+ requer legislação clara antidiscriminação, reconhecimento legal de identidade de gênero, direito à adoção, acesso igual a saúde reprodutiva. Educação deve normalizar diversidade sexual e de gênero desde infância, reduzindo preconceito. Empresas com políticas de diversidade e inclusão beneficiam: recrutam melhor talento, inovam mais, refletem sociedade que servem. Cultura de tolerância é responsabilidade coletiva. Quando sociedades reconhecem dignidade igual de pessoas LGBTQIA+, violência diminui, saúde mental melhora, economia se beneficia. Direitos humanos não são proposição parcial; são universais ou não são.',
800, '{"C1":{"score":98,"feedback":"Contextualização excepcional de violência e discriminação sistemática"},"C2":{"score":96,"feedback":"Argumentação sofisticada com soluções legislativas e culturais"},"C3":{"score":95,"feedback":"Reflexão crítica profunda sobre cidadania e dignidade"},"C4":{"score":94,"feedback":"Excelente domínio de linguagem e fluidez"},"C5":{"score":93,"feedback":"Conclusão poderosa sobre universalidade de direitos"}'::jsonb,
NOW() - INTERVAL '21 days'),
(:AMANDA_ID, 'Reforma agrária: justiça social através de redistribuição de terras',
'Concentração de terra é raiz de desigualdade estrutural brasileira. Minoria de latifundiários controla maioria das terras enquanto sem-terra morrem de fome. Modelo é historicamente insustentável e eticamente indefensável. Reforma agrária frequentemente é caricaturizada como radical; na verdade é necessidade de país maduro. Pequenos agricultores são mais produtivos por hectare, cultivam mais diversidade, são ambientalmente responsáveis. Reforma bem executada: distribui oportunidades, gera empregos rurais, sustenta comunidades, reduz êxodo urbano. Pressão em centros urbanos causada por concentração rural perpetua favelas. Países que realizaram reforma agrária (Taiwan, Coreia do Sul, Japão) desenvolveram-se rapidamente. Brasil adiou problema décadas por pressão de oligarquias. Reforma agrária deve incluir: distribuição de terras ociosas, crédito para produtores, capacitação técnica, acesso a mercados. Agroecologia pode substituir agronegócio destrutivo. Meio ambiente se beneficia: pequenas propriedades preservam mais biodiversidade. Desenvolvimento verdadeiro passa por redistribuição de terra.',
820, '{"C1":{"score":98,"feedback":"Contextualização magistral de concentração fundiária como raiz de desigualdade"},"C2":{"score":96,"feedback":"Argumentação sofisticada desmontando mitos sobre reforma agrária"},"C3":{"score":94,"feedback":"Reflexão crítica sobre sustentabilidade e desenvolvimento"},"C4":{"score":93,"feedback":"Excelente progressão argumentativa"},"C5":{"score":92,"feedback":"Conclusão que reafirma centralidade da questão"}'::jsonb,
NOW() - INTERVAL '14 days'),
(:AMANDA_ID, 'Democratização da cultura: arte como direito, não privilégio',
'Acesso a cultura é frequentemente tratado como luxo de elite; em verdade é direito fundamental e ferramenta de libertação. Periferias têm pouquíssimos museus, teatros, cinemas, bibliotecas. Crianças crescem sem contato com arte, limitando imaginação, criatividade, compreensão de humanidade. Cultura é educadora: nos humaniza, expande perspectivas, cura traumas. Sociedades que monopolizam arte em centros privilegiados desperdiçam potencial criativo vasto. Democratização exige investimento estatal: bibliotecas públicas bem equipadas, centros culturais em periferias, subsídios para artistas, acesso gratuito a museus. Tecnologia oferece oportunidades: plataformas digitais de arte, educação online. Mas presencial é insubstituível: energia viva de performance, experiência coletiva em exposição. Comunidades devem produzir própria cultura, não apenas consumir. Hip-hop, funk, arte urbana nasceram das ruas, mostrando criatividade quando acesso formal é bloqueado. Quando democratizamos cultura, potencializamos criatividade coletiva. Sociedades que valorizam arte de todos seus membros inovam mais, são mais humanas. Cultura não é enfeite; é constituinte de cidadania digna.',
860, '{"C1":{"score":99,"feedback":"Contextualização brilhante que articula cultura como direito e ferramenta"},"C2":{"score":98,"feedback":"Argumentação magistral integrando acesso, produção e impacto"},"C3":{"score":97,"feedback":"Reflexão crítica excepcional sobre criatividade e humanização"},"C4":{"score":96,"feedback":"Domínio extraordinário de linguagem"},"C5":{"score":95,"feedback":"Conclusão poderosa que universaliza valor cultural"}'::jsonb,
NOW() - INTERVAL '7 days'),
(:AMANDA_ID, 'Racismo estrutural: reparação histórica como fundação de justiça',
'Racismo não é fenômeno de preconceço individual superável com bom comportamento; é sistema que se reproduz através de instituições. Mesmo sem discriminação intencional explícita, estruturas perpetuam desvantagem racial. Mulheres negras morrem em parto 3x mais que brancas. Negros são encarcerados desproporcionalmente. Educação em áreas de maioria negra é inferior. Renda média de famílias negras é fração de famílias brancas. Essas disparidades não são acidentes; são legado não reparado de escravismo e segregação pós-abolição. Combater racismo estrutural requer ações deliberadas: educação histórica genuína reconhecendo atrocidades; políticas de ação afirmativa bem desenhadas para reparação; investimento robusto em comunidades marginalizadas; reforma de instituições com viés histórico (justiça, educação, saúde); inclusão de pessoas negras em posições de poder. Diversidade não é flavor do mês; é construção de democracia legítima. Quando negros estão em cadeiras de decisão, políticas mudam. Antirracismo não é favor a negros; é construção de justiça para todos. Brasil, país de maioria negra que minimiza herança africana, precisa reparação moral e material. Futuro justo requer reconhecimento de passado injusto e ação presente decidida.',
880, '{"C1":{"score":100,"feedback":"Contextualização magistral diferenciando racismo individual de estrutural"},"C2":{"score":100,"feedback":"Argumentação excepcional com evidência concreta de múltiplos setores"},"C3":{"score":99,"feedback":"Reflexão crítica profunda sobre reparação histórica e justiça"},"C4":{"score":99,"feedback":"Domínio extraordinário de linguagem com sofisticação"},"C5":{"score":99,"feedback":"Conclusão extraordinária que articula reconhecimento e ação"}'::jsonb,
NOW() - INTERVAL '0 days');

